function maxCollectedFruits(fruits) {
  const n = fruits.length;
  let total = 0;
  for (let i = 0; i < n; i++) {
    total += fruits[i][i];
  }

  // Best haul of the child from (0, n - 1): one row per move, staying right of the diagonal.
  function topRight(grid) {
    let dp = new Array(n).fill(-Infinity);
    dp[n - 1] = grid[0][n - 1];
    for (let i = 1; i < n - 1; i++) {
      const next = new Array(n).fill(-Infinity);
      for (let j = Math.max(i + 1, n - 1 - i); j < n; j++) {
        const best = Math.max(dp[j - 1], dp[j], j + 1 < n ? dp[j + 1] : -Infinity);
        next[j] = best + grid[i][j];
      }
      dp = next;
    }
    return dp[n - 1];
  }

  // The child from (n - 1, 0) moves like the one from (0, n - 1) on the transposed grid.
  const transposed = fruits.map((row, i) => row.map((_, j) => fruits[j][i]));
  return total + topRight(fruits) + topRight(transposed);
}

