function maxCollectedFruits(fruits) {
  const n = fruits.length;
  // Every route of exactly n - 1 moves that ends in the bottom-right room, as a list of room ids.
  const routes = (startRow, startCol, moves) => {
    const found = [];
    const walk = (i, j, path) => {
      if (path.length === n) {
        if (i === n - 1 && j === n - 1) found.push(path);
        return;
      }
      for (const [di, dj] of moves) {
        const a = i + di, b = j + dj;
        if (a >= 0 && a < n && b >= 0 && b < n) walk(a, b, [...path, a * n + b]);
      }
    };
    walk(startRow, startCol, [startRow * n + startCol]);
    return found;
  };
  const first = routes(0, 0, [[1, 1], [1, 0], [0, 1]]);
  const second = routes(0, n - 1, [[1, -1], [1, 0], [1, 1]]);
  const third = routes(n - 1, 0, [[-1, 1], [0, 1], [1, 1]]);
  let best = 0;
  for (const p of first) for (const q of second) for (const r of third) {
    let sum = 0;
    for (const room of new Set([...p, ...q, ...r])) sum += fruits[Math.floor(room / n)][room % n];
    best = Math.max(best, sum);
  }
  return best;
}

