function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 5);
  const top = size === 'large' || rand() < 0.3 ? 1000 : 9;
  const zeros = rand() * 0.5;
  return [Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < zeros ? 0 : Math.floor(rand() * (top + 1)))))];
}
